#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        long long k;
        cin >> n >> k;
        vector<int> ans;
        int s = n;
        while (s >= 1) {
            if (k >= s - 1 && s > 1) {
                ans.push_back(s);
                k -= (s - 1);
                --s;
            } else {
                if (k == 0) {
                    for (int i = 1; i <= s; ++i)
                        ans.push_back(i);
                } else {
                    ans.push_back((int)(k + 1));
                    for (int i = 1; i <= k; ++i)
                        ans.push_back(i);
                    for (int i = (int)(k + 2); i <= s; ++i)
                        ans.push_back(i);
                }
                break;
            }
        }
        for (size_t i = 0; i < ans.size(); ++i) {
            if (i > 0) cout << ' ';
            cout << ans[i];
        }
        cout << '\n';
    }
    return 0;
}
